('wizard_warlock','heir_of_hunger','{"id":"heir_of_hunger","name":"وارث گرسنگی","en":"Heir of Hunger","unlockLevel":8,"type":"summon_resource","target":"تمام دشمنان زنده","manaCostPercent":18,"cooldownTurns":3,"durationTurns":5,"description":"موجود گرسنگی برای 3 نوبت احضار می‌شود. هر بار دشمن مهارت اجرا کند، 2٪ حداکثر مانای مؤثرش را می‌بلعد و در مخزن گرسنگی ذخیره می‌کند (حداکثر 12٪). وارلاک در هر نوبت می‌تواند مخزن را به HP، MP یا قدرت ضربه بعدی تبدیل کند.","bossRules":"اگر دشمن مانا نداشته باشد، از انرژی ویژه‌اش تغذیه نمی‌کند؛ علیه باس سقف مخزن 6٪ است.","upgradeRanks":6,"upgrades":[{"rank":2,"pointsRequired":1,"effect":"رتبه 2: ضریب اثر اصلی 108٪ مقدار پایه؛ هزینه مانا 18٪ حداکثر مانای مؤثر.","bonus":"افزایش پایداری اثر و کاهش ۱ نوبت از زمان بازیابی در صورت وجود."},{"rank":3,"pointsRequired":2,"effect":"رتبه 3: ضریب اثر اصلی 116٪ مقدار پایه؛ هزینه مانا 18٪ حداکثر مانای مؤثر.","bonus":"افزایش ۵٪ شدت اثر اصلی."},{"rank":4,"pointsRequired":3,"effect":"رتبه 4: ضریب اثر اصلی 124٪ مقدار پایه؛ هزینه مانا 18٪ حداکثر مانای مؤثر.","bonus":"افزایش ۵٪ شدت و بهبود تعامل با اعتبار پیمان."},{"rank":5,"pointsRequired":4,"effect":"رتبه 5: ضریب اثر اصلی 132٪ مقدار پایه؛ هزینه مانا 17٪ حداکثر مانای مؤثر.","bonus":"افزایش ۵٪ شدت؛ محدودیت باس همچنان برقرار است."},{"rank":6,"pointsRequired":5,"effect":"رتبه 6: ضریب اثر اصلی 140٪ مقدار پایه؛ هزینه مانا 17٪ حداکثر مانای مؤثر.","bonus":"افزایش ۵٪ شدت و کاهش ۱٪ هزینه مانای پایه."},{"rank":7,"pointsRequired":6,"effect":"رتبه 7: ضریب اثر اصلی 148٪ مقدار پایه؛ هزینه مانا 17٪ حداکثر مانای مؤثر.","bonus":"استادکاری: افزایش ۱۰٪ شدت نهایی؛ بدون تغییر محدودیت استفاده در نبرد."}],"tags":["تغذیه","pact_debt"]}'::jsonb),
('wizard_warlock','true_name_shatter','{"id":"true_name_shatter","name":"شکستن نام حقیقی","en":"True Name Shatter","unlockLevel":9,"type":" 선택_debuff","target":"یک دشمن","manaCostPercent":20,"cooldownTurns":3,"durationTurns":5,"description":"یکی از چهار بند را می‌شکند: جسم (دفاع 22٪ کمتر)، اراده (حمله 20٪ کمتر)، جادو (قدرت مهارت 25٪ کمتر و هزینه مانا 15٪ بیشتر)، یا پیوند (حذف یک اثر مثبت غیرذاتی). اثر 3 نوبت؛ فقط یک بند هم‌زمان از این مهارت روی هر هدف فعال است.","bossRules":"روی باس‌ها شدت 50٪ است؛ حذف اثر مثبت باس فقط یک بار در هر نبرد مجاز است.","upgradeRanks":6,"upgrades":[{"rank":2,"pointsRequired":1,"effect":"رتبه 2: ضریب اثر اصلی 108٪ مقدار پایه؛ هزینه مانا 20٪ حداکثر مانای مؤثر.","bonus":"افزایش پایداری اثر و کاهش ۱ نوبت از زمان بازیابی در صورت وجود."},{"rank":3,"pointsRequired":2,"effect":"رتبه 3: ضریب اثر اصلی 116٪ مقدار پایه؛ هزینه مانا 20٪ حداکثر مانای مؤثر.","bonus":"افزایش ۵٪ شدت اثر اصلی."},{"rank":4,"pointsRequired":3,"effect":"رتبه 4: ضریب اثر اصلی 124٪ مقدار پایه؛ هزینه مانا 20٪ حداکثر مانای مؤثر.","bonus":"افزایش ۵٪ شدت و بهبود تعامل با اعتبار پیمان."},{"rank":5,"pointsRequired":4,"effect":"رتبه 5: ضریب اثر اصلی 132٪ مقدار پایه؛ هزینه مانا 19٪ حداکثر مانای مؤثر.","bonus":"افزایش ۵٪ شدت؛ محدودیت باس همچنان برقرار است."},{"rank":6,"pointsRequired":5,"effect":"رتبه 6: ضریب اثر اصلی 140٪ مقدار پایه؛ هزینه مانا 19٪ حداکثر مانای مؤثر.","bonus":"افزایش ۵٪ شدت و کاهش ۱٪ هزینه مانای پایه."},{"rank":7,"pointsRequired":6,"effect":"رتبه 7: ضریب اثر اصلی 148٪ مقدار پایه؛ هزینه مانا 19٪ حداکثر مانای مؤثر.","bonus":"استادکاری: افزایش ۱۰٪ شدت نهایی؛ بدون تغییر محدودیت استفاده در نبرد."}],"tags":["نام‌شکنی","pact_debt"]}'::jsonb),
