('wizard_necromancer','death_claw','{"id":"death_claw","name":"چنگال مرگ","en":"Death Claw","unlockLevel":1,"type":"damage","target":"یک دشمن","manaCostPercent":7,"cooldownTurns":0,"durationTurns":3,"description":"آسیب تاریک سنگین وارد می‌کند و زخم مرگ ۳ نوبتی می‌گذارد؛ زخم در پایان هر نوبت آسیب می‌زند. علیه هدف دارای نشان روحی آسیب بیشتر است. اگر هدف هنگام زخم مرگ کشته شود، ۱ روح ذخیره می‌شود.","bossRules":"باس: آسیب مستقیم کامل؛ آسیب زخم ۵۰٪.","upgradeRanks":6,"upgrades":[{"rank":2,"pointsRequired":1,"effect":"رتبه ۲: شدت اثر اصلی 108٪ مقدار پایه؛ آسیب تاریک سنگین وارد می‌کند و زخم مرگ ۳ نوبتی می‌گذارد؛ زخم در پایان هر نوبت آسیب می‌زند. علیه هدف دارای نشان روحی آسیب بیشتر است. اگر هدف هنگام زخم مرگ کشته شود، ۱ روح ذخیره می‌شود.","bonus":"ارتقای اختصاصی چنگال مرگ: افزایش کنترل‌شده اثر اصلی."},{"rank":3,"pointsRequired":2,"effect":"رتبه ۳: شدت اثر اصلی ۱۱۶٪ مقدار پایه؛ هزینه مانا بدون تغییر.","bonus":"ارتقای اختصاصی چنگال مرگ: افزایش کنترل‌شده اثر پایدار."},{"rank":4,"pointsRequired":3,"effect":"رتبه ۴: شدت اثر اصلی ۱۲۴٪ مقدار پایه؛ یک بهبود اختصاصی در تعامل مهارت.","bonus":"ارتقای اختصاصی چنگال مرگ: افزایش کنترل‌شده اثر ثانویه."},{"rank":5,"pointsRequired":4,"effect":"رتبه ۵: شدت اثر اصلی ۱۳۲٪ مقدار پایه؛ هزینه مانا ۱ واحد درصد کمتر.","bonus":"ارتقای اختصاصی چنگال مرگ: افزایش کنترل‌شده اثر تخصصی."},{"rank":6,"pointsRequired":5,"effect":"رتبه ۶: شدت اثر اصلی ۱۴۰٪ مقدار پایه؛ مدت اثر +۱ نوبت، اگر مهارت مدت‌دار باشد.","bonus":"ارتقای اختصاصی چنگال مرگ: افزایش کنترل‌شده اثر پیشرفته."},{"rank":7,"pointsRequired":6,"effect":"رتبه ۷: شدت اثر اصلی ۱۵۰٪ مقدار پایه؛ بازده ثانویه مهارت +۱۵٪. محدودیت‌های هدف و ظرفیت همچنان پابرجاست.","bonus":"ارتقای اختصاصی چنگال مرگ: افزایش کنترل‌شده اثر نهایی."}]}'::jsonb),
